/// What a family's states depend on beyond their position.
pub const Rules = struct {
    /// Tokens past the position a state read (Flash Next's MTP head keys row at-1 with token at: 1).
    lookahead: u32 = 0,
    /// Prompt kernels that change arithmetic with a chunk's rows: resume and keep only at the request's chunk starts.
    planned: bool = false,
    /// A mark other than the history's is kept only this far from every other mark and the resume point.
    min_gap: u32 = 256,
    /// Shorter prompts keep nothing: below it a mark's extra prompt call costs more than a later turn's reuse saves.
    min_prompt: u32 = 4096,
    /// TF_DS_EDIT_MARK=1 (edit_mark): an edit's stable mark clears the floor `from + min_gap` and `min_prompt / 4`
    /// rather than the history's half, so an edit in the first half of the history keeps its recovery mark.
    edit_mark: bool = false,
    /// Rows a resumed pass must still run past its state (DeepSeek's sliding window): a state nearer the end is passed over.
    tail: u32 = 0,
    /// The family's own resume grid (dsv41: its 2048-row chunk; 0: none): durable points and shared marks stand on it.
    grid: u32 = 0,
    /// The chunk end at or before a mark where its state is kept (dsv41's markEnds; 0: at the mark): the shared flags.
    chunk: u32 = 0,
    /// The rows a resumed pass replays at its end (dsv41: the window): a state is usable only this far from the end.
    window: u32 = 0,
    /// TF_DS_KEEP_PROTECT=1: a longer state counts as superseding only within its own conversation (`related`), so a
    /// fork's states never free their branch point first.
    keep_protect: bool = false,
    /// TF_DS_EXACT_RESUME=1: a pass keeps its own end as an off-grid state (dsv41: its chunk grid rounded down to even),
    /// whose tail the family holds the window's rows in; the family's usable is then the only resume gate.
    exact: bool = false,
    /// TF_DS_PROMPT_ENDSTATE=N (0178, M4): a pass's own end at `at == len` is kept (the full state: the replay built
    /// every ring), so an identical resent prompt resumes with zero rows to compute.
    endstate: bool = false,
    end_limit: u8 = 0,

    /// The native rule (Lanes.usable): 0 < at < len, on the grid, at most len - window, its lookahead inside the prompt.
    /// With `endstate` an exact `at == len` is offered too - the family's usable then confirms it is a full end state.
    pub fn eligible(r: Rules, at: u32, len: usize) bool {
        if (at == 0 or at > len) return false;
        if (@as(usize, at) == len) return r.endstate;
        if (r.grid > 0 and at % r.grid != 0) return false;
        return @as(usize, at) + r.window <= len and @as(usize, at) + r.lookahead <= len;
    }

    /// The grid point at or before `at` (`at` itself without a grid).
    pub fn floorGrid(r: Rules, at: u32) u32 {
        return if (r.grid == 0) at else at / r.grid * r.grid;
    }

    /// The largest position `eligible` allows for a prompt of `len` tokens (null: none).
    pub fn maxAt(r: Rules, len: usize) ?u32 {
        if (len < 2) return null;
        var hi: usize = len - 1;
        hi = @min(hi, len -| @max(r.window, r.lookahead));
        const at = r.floorGrid(@intCast(@min(hi, std.math.maxInt(u32))));
        return if (r.eligible(at, len)) at else null;
    }
};

pub const Entry = struct {
    tokens: []u32, // the state's tokens and `lookahead` more
    at: u32,
    saved: Saved,
    full_end: bool = false,
    bytes: u64,
    born: u32, // the length of the prompt that kept it: a later turn's is longer
    used: u64, // the store's clock at its last keep or resume
    last: []u32, // the last prompt that kept or resumed it
    shared: bool = false, // kept at a shared system block's cut: other conversations resume it, so its own never supersedes it
    group: u64 = 0, // the conversation that kept it (0111; 0: grouping off)
    point: ?u64 = null, // its durable point in the tier (written at keep, or restored from)
    images: bool = false, // its key holds pictures' keys
    restored: bool = false, // read back from the tier: not a turn's own state (it counts against no conversation)
    lineage: []Fork = &.{}, // the computation its rows belong to (store-owned; empty without a tier)
};

pub const Counts = struct {
    hits: u64 = 0,
    misses: u64 = 0,
    kept: u64 = 0,
    evicted: u64 = 0,
    refused: u64 = 0,
    failed: u64 = 0,
    // Each coarse counter's cause split (TF_DS_CACHE_METRICS; counted only while the switch is on).
    misses_no_prefix: u64 = 0,
    misses_tail_window: u64 = 0,
    misses_stale: u64 = 0,
    refused_budget: u64 = 0,
    refused_restores: u64 = 0,
    evicted_superseded: u64 = 0,
    evicted_lru: u64 = 0,
    failed_save: u64 = 0,
    failed_restore: u64 = 0,
};

/// Why a look-up found no usable kept state (the misses' split), closest to a hit first: a stale state was a hit but
/// for the family's rule, a passed-over one but for the tail/window rules, a mismatched one never was.
pub const MissCause = enum { no_prefix, tail_window, stale };

/// Raises `why` to the miss cause closer to a hit (MissCause's order).
fn worse(why: *MissCause, c: MissCause) void {
    if (@intFromEnum(c) > @intFromEnum(why.*)) why.* = c;
}

/// The resume depth of finished prompt passes (TF_DS_CACHE_METRICS): one observation per pass, the percent of its
/// prompt tokens a kept state resumed. The buckets are cumulative at 0/25/50/75/90/99/100 percent (the histogram's
/// edges), the last count the ones past every edge (never: a resumed fraction never passes 100).
pub const ResumeDepth = struct {
    counts: [bucket_edges.len + 1]u64 = @splat(0),
    /// Percent resumed, summed over the observations.
    total: f64 = 0,
    /// Passes observed.
    n: u64 = 0,

    pub const bucket_edges = [_]f64{ 0, 25, 50, 75, 90, 99, 100 };
    pub const help = "Percent of a finished prompt pass's prompt tokens that a kept prompt state resumed, one observation per pass (0/25/50/75/90/99/100 percent).";
};

/// Where a prompt pass starts and where it stops to keep its state (marks sorted, in `a`); `shared` names the keeps

