/// that stand at a shared cut (each cut's position as the family keeps it, marked or not; TF_DS_SHARED_PLAN).
pub const Plan = struct { from: u32 = 0, marks: []const u32 = &.{}, shared: []const u32 = &.{} };

/// The entry a backend restores itself (null: the pass starts at 0), the pass's marks and its shared keeps.
pub const Lookup = struct { entry: ?*Entry = null, marks: []const u32 = &.{}, shared: []const u32 = &.{} };

/// A side-effect-free look at what a prompt would resume: the best usable memory state, and a longer durable point.
pub const Probe = struct { memory: ?*Entry = null, durable: ?Point = null };

/// What a keep records beyond the state: its conversation, pictures and lineage (the tier writes them with it).
pub const KeepInfo = struct {
    group: u64 = 0,
    images: bool = false,
    media: []const Media = &.{}, // with pictures: each one's identity and the prompt's model ids (Kept's, for the tier)
    raw: []const u32 = &.{},
    parent: ?u64 = null,
    fork: u32 = 0,
    lineage: []const Fork = &.{}, // the pass's (Store.passLineage), copied into the entry
    shared: bool = false, // the state stands at a shared cut (Plan/Lookup's `shared`); TF_DS_SHARED_PLAN trusts it over the note ring
};

/// TF_DS_SHARED_PLAN=1: a kept state is flagged shared from the marks plan at the kept hook (off: the note ring).
pub fn sharedPlan(v: ?[]const u8) bool {
    return std.mem.eql(u8, v orelse "0", "1");
}

pub const Store = struct {
    gpa: Allocator,
    family: Snapshots,
    rules: Rules,
    budget: u64,
    held: u64 = 0,
    clock: u64 = 0,
    entries: std.ArrayList(*Entry) = .empty,
    counts: Counts = .{},
    // TF_DS_CACHE_METRICS (on; `0` turns it off): the cause splits and the resume depth counted for /metrics
    // (LaneHost sets it from the switch; off: this store counts neither, exactly as before).
    metrics: bool = false,
    depth: ResumeDepth = .{},
    shared_keys: std.ArrayList(u64) = .empty, // the tokens of recently planned shared cuts, hashed (at most SHARED_KEYS)
    shared_plan: bool = false, // TF_DS_SHARED_PLAN=1: keepWith flags shared from KeepInfo, not the note ring
    imprint: ?*imprint.Imprint = null, // --learn: shared cuts' states on disk, read back by later sessions and servers
    tier: ?Tier = null, // spill v2: kept states written at keep, read back by restore jobs (setTier)
    groups: bool = false, // 0111: kept states carry their conversation (setTier turns it on)
    next_group: u64 = 0,
    roots: std.AutoHashMapUnmanaged(u64, u32) = .empty, // each conversation's first prompt length (join)
