}

/// TF_DS_EXACT_RESUME's one reading (dsv41's off-grid end state and the cache's marks alike): on only when it is exactly
/// "1".
pub fn exactResume(v: ?[]const u8) bool {
    return std.mem.eql(u8, v orelse return false, "1");
}

/// TF_DS_PROMPT_ENDSTATE=N (0178, M4): keep a pass's own end state for an identical resent prompt, at most N at
/// once (null: unset, 0 or not a count in 1..8: off).
pub fn endState(v: ?[]const u8) ?u8 {
    const t = std.mem.trim(u8, v orelse return null, " \t\r\n");
    const n = std.fmt.parseInt(u8, t, 10) catch return null;
    return if (n >= 1 and n <= 8) n else null;
}

