    pub fn flush(s: *Store, budget_ns: u64) u64 {
        const t = s.tier orelse return 0;
        while (s.restoring.items.len > 0) s.restoreCancel(s.restoring.items[s.restoring.items.len - 1]);
        const left = t.vtable.flush(t.ptr, budget_ns);
        s.stats.flushes += 1;
        if (left > 0) {
