test "0178 (TF_DS_PROMPT_ENDSTATE): eligible offers at == len only with the flag" {
    const r: Rules = .{ .window = 128 };
    try std.testing.expect(!r.eligible(100, 100));
    try std.testing.expect(!r.eligible(50, 100));
    const e: Rules = .{ .window = 128, .endstate = true };
    try std.testing.expect(e.eligible(100, 100)); // the identical resend's full end state
    try std.testing.expect(!e.eligible(101, 100));
    try std.testing.expect(!e.eligible(0, 100));
}

test "TF_DS_PROMPT_ENDSTATE parses 1..8 and nothing else" {
    try std.testing.expectEqual(@as(?u8, null), endState(null));
    try std.testing.expectEqual(@as(?u8, null), endState("0"));
    try std.testing.expectEqual(@as(?u8, null), endState(""));
    try std.testing.expectEqual(@as(?u8, 2), endState("2"));
    for ([_][]const u8{ "x", "9", "-1" }) |bad| try std.testing.expectEqual(@as(?u8, null), endState(bad));
}

